"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["46706"],{69883(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.ato_duplicado_na_fase","status":422,"titulo":"A fase declara o mesmo tipo de ato com o mesmo papel mais de uma vez"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.ato_duplicado_na_fase","requisitos":["UNI-REQ-0157"],"oQueAconteceu":["Uma fase do cronograma declara, entre os produtos que publica, o mesmo tipo de ato\\ncom o mesmo papel duas ou mais vezes.","O tipo de ato identifica a mat\xe9ria publicada, e o papel diz se a publica\xe7\xe3o \xe9\\npreliminar, contra a qual cabe recurso quando o prazo de recurso \xe9 contado a partir dela, definitiva, que fecha o ciclo recursal, ou\\nsem papel. Declarado duas vezes com o mesmo papel, a fase passa a anunciar duas\\npublica\xe7\xf5es iguais da mesma mat\xe9ria, e n\xe3o h\xe1 como saber qual delas \xe9 a que vale.","Publicar o preliminar e o definitivo da mesma mat\xe9ria **n\xe3o** cai aqui: a fase\\ndeclara o mesmo tipo de ato duas vezes, uma com o papel preliminar e outra com o\\npapel definitivo. \xc9 o tipo de ato que liga o definitivo ao preliminar que ele\\nespera."],"comoResolver":["Remova a declara\xe7\xe3o repetida. A mensagem da recusa nomeia o c\xf3digo do ato que\\naparece mais de uma vez com o mesmo papel na fase.","Se a inten\xe7\xe3o era anunciar duas publica\xe7\xf5es diferentes da fase \u2014 um gabarito e um\\nresultado, por exemplo \u2014, declare o tipo de ato de cada uma. Se era anunciar o\\npreliminar e o definitivo da mesma mat\xe9ria, declare o mesmo tipo de ato duas vezes,\\numa com cada papel."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);